import {closeDetail} from './own-payroll-close-synthetic.js';
import {ownCloseSnapshot} from '../../assets/own-payroll-close-model.js';
import {ownRunHash} from '../../lib/internal-own-payroll-run.js';
import {emptyOwnReceiptParams} from '../../assets/own-payroll-receipt-model.js';
import {uid,hash} from './own-payroll-program-synthetic.js';
export function receiptSnapshot(count=35){const original=ownCloseSnapshot(closeDetail(count),{kind:'all',values:[]}),groupId=uid(400),records=original.employees.map((e,i)=>({...Object.fromEntries(['contractId','employeeNumber','agreementCode','departmentCode','runId','liquidationVersion','precision'].map(k=>[k,e[k]])),sourceGroupId:groupId,personId:uid(20000+i),registrationId:uid(30000+i),name:'Agente sintético '+i,dni:String(99000100+i),cuil:String(20990001000+i),totals:Object.fromEntries(Object.entries(e.totals).filter(([k])=>k!=='contractId')),concepts:original.concepts.filter(c=>c.contractId===e.contractId).map(c=>({code:c.conceptCode,label:'Etiqueta conservada sintética '+c.conceptCode,nature:c.nature,unit:c.unit,amount:c.amount,labelSourceSha256:hash('d')}))}));return {version:'own-receipt-snapshot.v1',params:{...emptyOwnReceiptParams(original.period),issuer:{name:'Municipio de ensayo sintético',taxId:'30990000001',address:'Domicilio inventado 123'},legend:'Sólo prueba sintética'},sourceVersion:hash('b'),sources:[{id:groupId,snapshotSha256:ownRunHash(original),period:original.period,type:original.liquidationType,employeeCount:count,populationCount:count,selectedCount:count}],records,recordCount:count,conceptCount:records.reduce((n,r)=>n+r.concepts.length,0),identityBasis:'native_registration_immutable',paymentDateBasis:'declared',signatureState:'pending',payrollPosted:false,paymentExecuted:false};}
export function receiptPreview(count=35){const snapshot=receiptSnapshot(count);return {version:'own-receipt-preview.v1',scopeVersion:hash('a'),snapshot,snapshotSha256:ownRunHash(snapshot),permissions:{canPrepare:true}};}
export function receiptBatch(count=35){const p=receiptPreview(count);return {version:'own-receipt-batch.v1',id:uid(800),preparedAt:'2026-10-05T15:00:00Z',preparedBy:'Preparador sintético',snapshot:p.snapshot,snapshotSha256:p.snapshotSha256,state:'prepared',sourceCurrent:true,review:null,permissions:{canApprove:true,canWithdraw:true,canDownload:true}};}
export function receiptCommand(){const p=receiptPreview(2);return {command:'prepare',scopeVersion:p.scopeVersion,sourceVersion:p.snapshot.sourceVersion,params:p.snapshot.params,batchId:null,batchSha256:null,reason:'Motivo exclusivamente sintético',reviewConfirmed:false};}
export function receiptEvent(){const body=receiptCommand();return {version:'own-receipt-event.v1',id:uid(800),key:uid(9),body,bodySha256:ownRunHash(body),batchId:uid(800),recordedAt:'2026-10-05T15:00:00Z',replayed:false};}
export function receiptSelf(){const s=receiptSnapshot(2);return {version:'own-receipt-self.v1',items:[{batchId:uid(800),preparedAt:'2026-10-05T15:00:00Z',approvedAt:'2026-10-05T16:00:00Z',params:Object.fromEntries(Object.entries(s.params).filter(([k])=>!['types','filters'].includes(k))),record:s.records[0],source:Object.fromEntries(Object.entries(s.sources[0]).filter(([k])=>!['employeeCount','populationCount','selectedCount'].includes(k))),signatureState:'pending',paymentDateBasis:'declared',payrollPosted:false,paymentExecuted:false}]};}
